import re

def parse(lines):
    master = {}
    mlines = []
    alts = []
    alines = []
    slaves = []
    slines = []
    gslaves = []
    glines = []
    skip = []
    cur = None
    for i, l in enumerate(lines):
        if not l.strip():
            continue
        m = re.match(r'^\s+(?P<slave>\S+)\s+(?P<path>\S.*?)\s*$', l)
        if m:
            if cur is None:
                gslaves.append({'Slave': m.group('slave'), 'Link': m.group('path')})
                glines.append(i)
            else:
                slaves.append({'Alternative': cur['Alternative'], 'Slave': m.group('slave'), 'Path': m.group('path')})
                slines.append(i)
            continue
        m = re.match(r'^(?P<key>[^:\s][^:]*):\s*(?P<value>.*?)\s*$', l)
        if m:
            k = m.group('key').strip()
            v = m.group('value')
            if k == 'Slaves' and v == '':
                skip.append(i)
                continue
            if re.match(r'^-?\d+$', v):
                v = int(v)
            if k == 'Alternative':
                cur = {'Alternative': v}
                alts.append(cur)
                alines.append(i)
                continue
            if cur is not None:
                cur[k] = v
                alines.append(i)
            else:
                master[k] = v
                mlines.append(i)
    keys = []
    for a in alts:
        for k in a:
            if k not in keys:
                keys.append(k)
    alts = [{k: a.get(k, '') for k in keys} for a in alts]
    blocks = []
    if master:
        blocks.append({'name': 'link_group', 'kind': 'kv', 'lines': mlines, 'records': [master]})
    if gslaves:
        blocks.append({'name': 'link_group_slaves', 'kind': 'table', 'lines': glines, 'records': gslaves})
    if alts:
        blocks.append({'name': 'alternatives', 'kind': 'table', 'lines': alines, 'records': alts})
    if slaves:
        blocks.append({'name': 'slaves', 'kind': 'table', 'lines': slines, 'records': slaves})
    return {'blocks': blocks, 'skip': skip}
